<script setup>
import { Banknote, BookOpenCheck, PieChart } from '@lucide/vue';
import { computed, onMounted, ref } from 'vue';import { api } from '../../services/api.js';
const report=ref(null),loading=ref(true);onMounted(async()=>{try{const response=await api.get('/admin/reports');report.value=response.data.data}finally{loading.value=false}});
const maxBookings=computed(()=>Math.max(1,...(report.value?.daily.map(item=>item.bookings)??[1])));const peso=value=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP',maximumFractionDigits:0}).format(value??0);
</script>
<template><section class="page admin-page"><div class="page-header"><div><span class="eyebrow">Data from real bookings</span><h1 class="page-title">Reports & analytics</h1><p class="muted">A 30-day operational view using Asia/Manila reporting dates.</p></div></div><div v-if="loading" class="skeleton" style="height:380px"></div><template v-else><div class="summary"><article class="card"><BookOpenCheck/><span>Total bookings</span><strong>{{ report.totals.totalBookings }}</strong></article><article class="card"><Banknote/><span>Completed fare total</span><strong>{{ peso(report.totals.fareTotal) }}</strong></article><article class="card"><PieChart/><span>Shared bookings</span><strong>{{ report.rideTypes.find(item=>item._id==='shared')?.count??0 }}</strong></article></div><article class="chart-card card"><div><span class="eyebrow">Last 30 days</span><h2>Daily booking volume</h2></div><div v-if="!report.daily.length" class="empty-state">No booking activity in this period.</div><div v-else class="chart" role="img" aria-label="Daily bookings bar chart"><div v-for="item in report.daily" :key="item._id" class="bar-column"><span class="value">{{ item.bookings }}</span><div class="bar" :style="{height:`${Math.max(8,(item.bookings/maxBookings)*180)}px`}"></div><small>{{ item._id.slice(5) }}</small></div></div></article><article class="chart-card card"><div><span class="eyebrow">Ride preference</span><h2>Shared versus private</h2></div><div class="type-list"><div v-for="item in report.rideTypes" :key="item._id"><span>{{ item._id==='shared'?'Shared ride':'Private ride' }}</span><strong>{{ item.count }}</strong></div></div></article></template></section></template>
<style scoped>.admin-page{max-width:1100px}.summary{display:grid;gap:12px}.summary article{display:grid;grid-template-columns:auto 1fr;gap:4px 11px;padding:17px}.summary svg{grid-row:1/3;color:var(--color-primary)}.summary span{color:var(--color-text-soft);font-size:.69rem}.summary strong{font-size:1.15rem}.chart-card{margin-top:16px;padding:19px}.chart-card h2{font-size:1rem}.chart{display:flex;min-height:235px;align-items:end;gap:8px;overflow-x:auto;padding:18px 3px 3px}.bar-column{display:grid;min-width:28px;justify-items:center;gap:5px}.bar{width:20px;border-radius:7px 7px 2px 2px;background:linear-gradient(#10b981,#047857)}.value,.bar-column small{color:var(--color-text-soft);font-size:.56rem}.type-list{display:grid;gap:9px}.type-list div{display:flex;justify-content:space-between;padding:12px;border-radius:10px;background:#f8fafc;font-size:.78rem}@media(min-width:650px){.summary{grid-template-columns:repeat(3,1fr)}}</style>

